import openpyxl
from openpyxl.styles import Font

wb = openpyxl.load_workbook('init.xlsx')
ws = wb['Sheet1']

# Apply '等线' font to the entire sheet
for row in ws.iter_rows():
    for cell in row:
        cell.font = Font(name='等线')

# Set number formats for columns N, O, P (rows 7-23)
# Use #,##0.## for non-whole numbers, General for whole numbers
for r in range(7, 24):
    for col in ['N', 'O', 'P']:
        cell = ws[f'{col}{r}']
        val = cell.value
        if val is None:
            cell.number_format = 'General'
        elif isinstance(val, float) and val == int(val):
            cell.number_format = 'General'
        else:
            cell.number_format = '#,##0.##'

# Compute and set N and O values
for r in range(7, 24):
    n_val = ws[f'N{r}'].value
    if n_val is None:
        continue
    if n_val > 40:
        ws[f'N{r}'].value = 40
        ws[f'O{r}'].value = n_val - 40
    else:
        ws[f'O{r}'].value = None

wb.save('output.xlsx')
print("done")
